import { useState } from 'react';

type Plan = { id: string; title: string; price: string };
type Props = { plans: Plan[] };

export default function {{component_name}}({ plans }: Props) {
  const [picked, setPicked] = useState(plans[0]?.id);
  return (
    <div className="grid grid-cols-3 gap-3">
      {plans.map((p) => (
        <button
          key={p.id}
          onClick={() => setPicked(p.id)}
          className={`p-4 border rounded text-left ${picked === p.id ? 'border-blue-500 bg-blue-50' : ''}`}
        >
          <div className="font-bold">{p.title}</div>
          <div>{p.price}</div>
        </button>
      ))}
    </div>
  );
}
